# prefix KNOWN to have leaked — including `yitc-verify-sandbox-` (audit-pre HIGH absorption: a floor
# that omitted the one prefix this task exists for would silently restore the exact 2026-08-09 bug if
# discovery ever read nothing).
_TMP_BASELINE_PREFIXES = ("yitc-pinned-verify-", "yitc-pinned-engine-", "yitc-verify-sandbox-")


